package com.videomind.module.auth;import io.jsonwebtoken.Claims;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.Arrays;import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;
@Component public class JwtAuthenticationFilter extends OncePerRequestFilter{private final JwtService jwt;public JwtAuthenticationFilter(JwtService j){jwt=j;}@Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String t=token(r);if(t!=null)try{Claims p=jwt.parse(t);Long id=Long.valueOf(p.getSubject());SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(id,t,java.util.List.of()));}catch(Exception ignored){}c.doFilter(r,s);}private String token(HttpServletRequest r){String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))return h.substring(7);if(r.getCookies()!=null)return Arrays.stream(r.getCookies()).filter(x->"VM_ACCESS".equals(x.getName())).map(Cookie::getValue).findFirst().orElse(null);return null;}}
